import{_ as n,C as i,o as l,c as g,j as o,a,E as s,a2 as r}from"./chunks/framework.BxGh02fV.js";const k=JSON.parse('{"title":"Backlog","description":"","frontmatter":{"title":"Backlog"},"headers":[],"relativePath":"en/guide/backlog.md","filePath":"en/guide/backlog.md"}'),h={name:"en/guide/backlog.md"};function d(c,t,u,p,m,y){const e=i("Capture");return l(),g("div",null,[t[0]||(t[0]=o("h1",{id:"backlog",tabindex:"-1"},[a("Backlog "),o("a",{class:"header-anchor",href:"#backlog","aria-label":'Permalink to "Backlog"'},"​")],-1)),t[1]||(t[1]=o("p",null,[a("The backlog is the screen where you organise and understand the work. Its tree has two roots: "),o("strong",null,"Registry"),a(", the product's evolution registry and its lots, and "),o("strong",null,"Project"),a(", which holds the session history and, below it, the epics, their stories and their tasks. Every item in the tree has its own page, which says what it frames and what it contains.")],-1)),s(e,{name:"backlog",alt:"The Backlog screen on the Project root: the last session and the session history"}),t[2]||(t[2]=r('<h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><ul><li><strong>Scope</strong> (left column): a <strong>Search…</strong> field, the <strong>Status</strong> filter (<strong>All</strong> or <strong>Hide done</strong>), then the tree: <strong>Registry</strong>, <strong>Project — Workshop</strong>, and under it the numbered epics, which you expand down to stories and then tasks. As soon as the project spans more than one year, a <strong>Vintage</strong> filter appears, and search results are sorted by year.</li><li><strong>Right panel</strong>: the page of the selected item.</li></ul><h2 id="the-pages" tabindex="-1">The pages <a class="header-anchor" href="#the-pages" aria-label="Permalink to &quot;The pages&quot;">​</a></h2><h3 id="project-—-the-session-history" tabindex="-1">Project — the session history <a class="header-anchor" href="#project-—-the-session-history" aria-label="Permalink to &quot;Project — the session history&quot;">​</a></h3><p>The <strong>Project</strong> root shows the <strong>Last session</strong>, with its summary, then the list of sessions, most recent first. The source is stated:</p><ul><li><strong>Kessho</strong>, if your Kessho memory knows this repository: Effortless queries it and shows its session archives;</li><li>otherwise <strong>Effortless (this machine)</strong>: every time an agent works on the project through the MCP server, Effortless records the session (its client, the verbs called, the tasks touched, the number of commits), and the agent can write a summary into it. These sessions stay on your machine; they are not versioned.</li></ul><p>If a source could not be read, the page says so (&quot;Not read: …&quot;) and gives the reason on hover.</p><h3 id="registry-—-evolutions-and-lots" tabindex="-1">Registry — evolutions and lots <a class="header-anchor" href="#registry-—-evolutions-and-lots" aria-label="Permalink to &quot;Registry — evolutions and lots&quot;">​</a></h3>',8)),s(e,{name:"backlog-registre",alt:"The Registry root: the evolution registry and the Lots tab"}),t[3]||(t[3]=r('<p>The <strong>Registry</strong> root opens two tabs, <strong>Evolution registry</strong> and <strong>Lots</strong>. The table lists each evolution: identifier, <strong>Type</strong> (Anomaly, Improvement, Feature, Discovery, Test), title, <strong>Status</strong>, <strong>Criticality</strong> and <strong>Priority</strong>. Clicking a column header sorts the table. Above it: <strong>Search (id, title, detail)…</strong>, the <strong>Marker</strong> filters and <strong>Hide Resolved/Retired</strong>.</p><p>Clicking an evolution&#39;s title opens the <strong>Evolution detail</strong> drawer.</p><p>The <strong>Lots</strong> tab shows &quot;Lots to graduate&quot;: each lot lists its evolutions in the order they will be graduated.</p><h3 id="epic-—-what-it-frames-and-its-stories" tabindex="-1">Epic — what it frames and its stories <a class="header-anchor" href="#epic-—-what-it-frames-and-its-stories" aria-label="Permalink to &quot;Epic — what it frames and its stories&quot;">​</a></h3>',4)),s(e,{name:"backlog-epic",alt:"An epic's page: what it frames, then its stories"}),t[4]||(t[4]=r('<p>An epic&#39;s page says <strong>What the epic frames</strong> (its description), then lists its <strong>stories</strong>, each with its phase and status; a click opens the story. Below: <strong>New story</strong>, <strong>Close the epic</strong> and the breakdown <strong>Drafts</strong> — candidate stories, with their status (draft, submitted, materialized, rejected).</p><h3 id="story-—-what-it-frames-and-its-tasks" tabindex="-1">Story — what it frames and its tasks <a class="header-anchor" href="#story-—-what-it-frames-and-its-tasks" aria-label="Permalink to &quot;Story — what it frames and its tasks&quot;">​</a></h3>',2)),s(e,{name:"backlog-story",alt:"A story's page: what it frames, then its tasks"}),t[5]||(t[5]=r('<p>A story&#39;s page shows whether it is the <strong>Active story</strong> or an <strong>Inactive story</strong>, and how many tasks are done (&quot;2/5 tasks done&quot;). It says <strong>What the story frames</strong> (its objective, editable), then lists its <strong>tasks</strong> with their status; a click opens the task. Below: <strong>Activate</strong>, <strong>Close</strong>, the <strong>Proposal</strong> and the <strong>Reloop</strong> block, whose <strong>Rewind</strong> button sends the story back to an earlier phase.</p><h3 id="task-—-what-to-do-and-what-it-produced" tabindex="-1">Task — what to do and what it produced <a class="header-anchor" href="#task-—-what-to-do-and-what-it-produced" aria-label="Permalink to &quot;Task — what to do and what it produced&quot;">​</a></h3>',2)),s(e,{name:"backlog-tache",alt:"A task's page: what needs to be done, what it produced, its commits"}),t[6]||(t[6]=r('<p>A task&#39;s page shows its reference (for example <code>26E2S1T1</code>), its status, its phase and, once closed, its date (&quot;closed on …&quot;), then three sections:</p><ul><li><strong>What needs to be done</strong>: the task&#39;s description, editable;</li><li><strong>What the task produced</strong>: its result, as observed, editable — the agent fills it in when closing the task;</li><li><strong>Task&#39;s commits</strong>: the commits whose message cites its reference.</li></ul><p>The link at the top of the page goes back to its story.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><ul><li><strong>Create an epic</strong>: on the Project root, <strong>New epic</strong> asks for a <strong>Zone</strong> and a <strong>Title</strong>; the <strong>Description (optional)</strong> can stay empty.</li><li><strong>Create a story</strong>: on an epic, <strong>New story</strong> asks for a <strong>Title</strong>, and optionally a <strong>Slug</strong> and <strong>Dependencies</strong>.</li><li><strong>Propose a breakdown</strong>: on an epic, <strong>Draft</strong> opens a form (<strong>Title</strong>, <strong>Summary</strong>, <strong>Nature</strong> <code>opale</code> or <code>fix</code>, <strong>Rationale (optional)</strong>), then <strong>Create the draft</strong>. Each draft offers <strong>Edit</strong>, <strong>Submit</strong>, <strong>Validate → Story</strong> (the story appears in the tree) and <strong>Reject</strong>.</li><li><strong>Activate and close</strong>: <strong>Activate</strong> makes a story the active one; <strong>Close</strong> requires all its tasks to be <strong>Done</strong>; <strong>Close the epic</strong> requires all its stories to be finished.</li><li><strong>Propose and rewind</strong>: write the <strong>Proposal</strong> in its text box, then <strong>Save</strong>, <strong>Validate</strong> or <strong>Reject</strong>. For the <strong>Reloop</strong>, pick the phase in &quot;Choose a target phase…&quot;, then <strong>Rewind</strong>; if the story is not active, the reloop activates it first, and the screen says so.</li><li><strong>Add an evolution</strong>: in the registry, <strong>Add</strong> asks for a type and a title.</li><li><strong>Sort evolutions</strong>: in the table, type the <strong>Criticality</strong> (1 Blocking, 2 Major, 3 Minor) and the <strong>Priority</strong>; the value is saved when you leave the field. An anomaly can be requalified as an improvement, and the other way round, with the &quot;→ Improvement&quot; or &quot;→ Anomaly&quot; button on its row; other types cannot be requalified.</li><li><strong>Mark or cancel an evolution</strong>: in the <strong>Evolution detail</strong> drawer, <strong>Mark ready to graduate</strong> (or <strong>Unmark</strong>), and <strong>Cancel</strong>, which asks for a <strong>Cancellation reason</strong>.</li><li><strong>Build a lot</strong>: tick evolutions (<strong>Select all</strong>, <strong>Clear selection</strong>), then <strong>Create a batch from the selection</strong>. In the <strong>Lots</strong> tab, <strong>New lot</strong> creates an empty lot; within a lot, <strong>Move up</strong> and <strong>Move down</strong> order the evolutions, <strong>Remove from lot</strong> takes one out, <strong>Add an evolution</strong> only offers evolutions ready to graduate, and <strong>Remove</strong> deletes the lot after confirmation.</li></ul><h2 id="with-an-ai-agent" tabindex="-1">With an AI agent <a class="header-anchor" href="#with-an-ai-agent" aria-label="Permalink to &quot;With an AI agent&quot;">​</a></h2><p><code>effortless_epic_start</code> and <code>effortless_story_start</code> create epics and stories; <code>effortless_task_update</code> also carries a task&#39;s <code>result</code>; <code>effortless_sessions</code> returns the session history shown on the Project root, and <code>effortless_session_summary</code> writes the summary of the current session; <code>effortless_evolution_add</code> and <code>effortless_evolution_graduate</code> keep the registry.</p>',7))])}const w=n(h,[["render",d]]);export{k as __pageData,w as default};
